package com.smartgrocery.controller; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1") public class HealthController {@GetMapping("/health") public Map<String,String> health(){return Map.of("status","UP","application","smart-grocery-store");} @PostMapping("/ai/parse-stock-command") public Map<String,Object> parse(@RequestBody Map<String,String> body){String text=body.getOrDefault("command","");return Map.of("command",text,"providerConfigured",false,"message","Configure a speech/translation provider; confirm parsed product and quantity manually.");}}